-- =====================================================================
-- V2 : Jeu de donnees de test
-- On insere avec des id explicites (colonnes GENERATED BY DEFAULT le
-- permettent), puis on RESTART l'identite pour que les prochains INSERT
-- applicatifs ne rentrent pas en collision avec les id du seed.
-- =====================================================================



-- Repositionne les generateurs d'identite au-dessus des id deja utilises.
ALTER TABLE observatoire ALTER COLUMN id RESTART WITH 100;
ALTER TABLE exoplanete   ALTER COLUMN id RESTART WITH 100;
